css:
.pks1-root{position:absolute;inset:0;overflow:hidden;background:var(--wa-bg, #05050a);z-index:5;font-family:"Pretendard","Pretendard Variable","Malgun Gothic",-apple-system,system-ui,sans-serif;font-size:16px;font-weight:400;font-style:normal;line-height:normal;letter-spacing:normal;color:var(--wa-text, #fff);text-align:left;text-transform:none;word-spacing:normal;-webkit-font-smoothing:antialiased}
.pks1-root,.pks1-root *,.pks1-root *::before,.pks1-root *::after{box-sizing:border-box}
.pks1-root *{margin:0;padding:0;border:0 solid transparent;background:none;font:inherit;color:inherit;text-decoration:none}
.pks1-root img{display:block;border:0;max-width:none}
.pks1-root [hidden]{display:none!important}
.pks1-root .nI1_9712_1_10319{align-content:stretch;display:flex;align-items:center;justify-content:space-between;position:relative;flex-shrink:0;width:100%}
.pks1-root .nI1_9712_1_10320{align-content:stretch;display:flex;align-items:center;position:relative;flex-shrink:0}
.pks1-root .nI1_9712_1_10321{word-break:break-word;font-family:"Pretendard","Pretendard Variable","Malgun Gothic",-apple-system,system-ui,sans-serif;font-weight:600;line-height:19px;font-style:normal;position:relative;flex-shrink:0;font-size:16px;color:var(--wa-text, #fff);white-space:nowrap;width:73px}
.pks1-root .nI1_9712_1_10326{position:relative;flex-shrink:0;width:20px;height:20px}
.pks1-root .x169{position:absolute;display:block;inset:0;max-width:none;width:100%;height:100%}
.pks1-root[data-theme="light"]{background:var(--wa-bg, #eef2f7);color:var(--wa-text, #0e1a2b)}
.pks1-root[data-theme="light"] [data-name="Background"] > img{filter:invert(1) hue-rotate(180deg) saturate(0.4) brightness(1.05);opacity:0.5}
.pks1-root[data-theme="light"] [data-name="Building Image"] img{filter:saturate(0.92) brightness(0.98)}
.pks1-root[data-theme="light"] [data-name="Floor Plan"] img{filter:invert(1) hue-rotate(180deg) saturate(0.55) brightness(1.04)}
.pks1-root[data-theme="light"] [data-name^="Popup/"] > [data-name="Background"]::after{content:"";position:absolute;inset:0;border-radius:inherit;background:color-mix(in srgb, var(--wa-bg, rgb(247 250 254)) 92%, transparent);pointer-events:none}
.pks1-root[data-theme="light"] .nI1_9712_1_10321{color:var(--wa-text, #10231d)}
